KG_CODE("f:tests/test_core.py","\"\"\"Tests for the safety-critical logic.\n\nScope is deliberate: these cover the parts where a silent mistake is dangerous\n(permissions, secret redaction, ref staleness, key parsing, the AX join) rather\nthan chasing coverage of glue code. They run headless with no daemon, no\nbrowser and no UI, so they work in CI.\n\nRun:  python -m pytest tests/ -q        (or: python tests/test_core.py)\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport sys\nimport time\nimport unittest\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / \"src\"))\n\nfrom autoskill.browser import perceive, reaper              # noqa: E402\nfrom autoskill.desktop import uia                           # noqa: E402\nfrom autoskill.desktop.actions import _escape_sendkeys, _to_sendkeys  # noqa: E402\nfrom autoskill.desktop.refs import RefStore, parse_ref      # noqa: E402\nfrom autoskill.protocol import (EffectState, ErrorCode, ProtocolError,  # noqa: E402\n                                Request, Response)\nfrom autoskill.safety.audit import redact                   # noqa: E402\nfrom autoskill.safety.permissions import (PermissionEngine, PermissionMode,  # noqa: E402\n                                          PermissionPolicy, Risk)\n\n\nclass TestPermissions(unittest.TestCase):\n    def engine(self, mode: PermissionMode) -> PermissionEngine:\n        return PermissionEngine(PermissionPolicy(mode=mode))\n\n    def test_no_app_deny_list_after_cua_realignment(self):\n        \"\"\"Owner decision 2026-10-11: process/title never refuse; the\n        decision is risk class + mode only (CUA-aligned).\"\"\"\n        for mode in PermissionMode:\n            d = self.engine(mode).check(\"desktop.click\",\n                                        process=\"KeePass.exe\",\n                                        title=\"My Bank - Login\")\n            self.assertTrue(d.allowed, f\"process/title refused in {mode.value}\")\n        read = self.engine(PermissionMode.FULL).check(\n            \"desktop.observe\", process=\"KeePass.exe\")\n        self.assertTrue(read.allowed)\n\n    def test_strict_confirms_every_action(self):\n        d = self.engine(PermissionMode.STRICT).check(\n            \"desktop.click\", process=\"notepad.exe\")\n        self.assertTrue(d.allowed)\n        self.assertTrue(d.needs_confirmation)\n\n    def test_reads_are_never_gated(self):\n        \"\"\"Observation must stay free, or the agent acts blind.\"\"\"\n        for mode in (PermissionMode.STRICT, PermissionMode.GUARDED):\n            d = self.engine(mode).check(\"desktop.observe\", process=\"unknown.exe\")\n            self.assertTrue(d.allowed)\n            self.assertFalse(d.needs_confirmation)\n\n    def test_shutdown_is_never_gated(self):\n        \"\"\"The emergency brake cannot require the agent's cooperation.\"\"\"\n        for mode in PermissionMode:\n            d = self.engine(mode).check(\"system.shutdown\")\n            self.assertTrue(d.allowed)\n            self.assertFalse(d.needs_confirmation)\n\n    def test_guarded_allows_listed_app_without_prompt(self):\n        d = self.engine(PermissionMode.GUARDED).check(\n            \"desktop.click\", process=\"notepad.exe\")\n        self.assertTrue(d.allowed)\n        self.assertFalse(d.needs_confirmation)\n\n    def test_guarded_allows_unlisted_routine_app(self):\n        d = self.engine(PermissionMode.GUARDED).check(\n            \"desktop.click\", process=\"some-random-app.exe\")\n        self.assertTrue(d.allowed)\n        self.assertFalse(d.needs_confirmation)\n\n    def test_unknown_verb_is_treated_as_destructive(self):\n        \"\"\"Fail closed: an unmapped method must not default to harmless.\"\"\"\n        e = self.engine(PermissionMode.GUARDED)\n        self.assertIs(e.risk_of(\"desktop.launch_missiles\"), Risk.DESTRUCTIVE)\n\n    def test_full_mode_allows_ordinary_actions(self):\n        d = self.engine(PermissionMode.FULL).check(\n            \"desktop.click\", process=\"anything.exe\")\n        self.assertTrue(d.allowed)\n        self.assertFalse(d.needs_confirmation)\n\n\nclass TestRedaction(unittest.TestCase):\n    def test_secret_keys_masked(self):\n        out = redact({\"password\": \"hunter2\", \"api_key\": \"abc\", \"user\": \"amal\"})\n        self.assertEqual(out[\"password\"], \"[redacted]\")\n        self.assertEqual(out[\"api_key\"], \"[redacted]\")\n        self.assertEqual(out[\"user\"], \"amal\")\n\n    def test_secret_shaped_values_masked_regardless_of_key(self):\n        out = redact({\"note\": \"ghp_\" + \"a\" * 30})\n        self.assertEqual(out[\"note\"], \"[redacted]\")\n\n    def test_nested(self):\n        out = redact({\"a\": {\"b\": {\"token\": \"xyz\"}}})\n        self.assertEqual(out[\"a\"][\"b\"][\"token\"], \"[redacted]\")\n\n    def test_long_values_truncated(self):\n        out = redact({\"text\": \"x\" * 2000})\n        self.assertLessEqual(len(out[\"text\"]), 501)\n\n    def test_cycle_depth_guard(self):\n        deep: dict = {}\n        cur = deep\n        for _ in range(30):\n            cur[\"n\"] = {}\n            cur = cur[\"n\"]\n        redact(deep)  # must not recurse without bound\n\n\nclass TestRefStore(unittest.TestCase):\n    def test_parse_forms(self):\n        for token in (\"@e3\", \"e3\", \"3\"):\n            self.assertEqual(parse_ref(token), \"@e3\")\n\n    def test_malformed_ref_rejected(self):\n        for bad in (\"@x1\", \"\", \"@e0\", \"abc\"):\n            with self.assertRaises(ProtocolError):\n                parse_ref(bad)\n\n    def test_new_observation_invalidates_old_refs(self):\n        \"\"\"The core guarantee: a ref never resolves against a later screen.\"\"\"\n        store = RefStore()\n        store.begin_observation()\n        ref = store.add(object(), role=\"button\", name=\"OK\")\n        store.resolve(ref)                 # valid now\n        store.begin_observation()          # screen changed\n        with self.assertRaises(ProtocolError) as ctx:\n            store.resolve(ref)\n        self.assertEqual(ctx.exception.error.code, ErrorCode.UNKNOWN_REF)\n\n    def test_unknown_ref_before_any_observation(self):\n        store = RefStore()\n        with self.assertRaises(ProtocolError) as ctx:\n            store.resolve(\"@e1\")\n        self.assertIn(\"nothing has been observed\", ctx.exception.error.message)\n\n    def test_every_error_carries_a_hint(self):\n        \"\"\"An agent recovers from the hint, not the message.\"\"\"\n        store = RefStore()\n        try:\n            store.resolve(\"@e1\")\n        except ProtocolError as exc:\n            self.assertTrue(exc.error.hint)\n\n\nclass TestKeyParsing(unittest.TestCase):\n    def test_combos(self):\n        \"\"\"uiautomation wants `{Ctrl}s`, not the Win32 `^s` shorthand.\n\n        Emitting `^` sent a literal caret and the combination did nothing,\n        while the call still reported success - `Ctrl+Shift+N` in File Explorer\n        created no folder. The original version of this test asserted the wrong\n        target syntax, so it passed the whole time.\n        \"\"\"\n        self.assertEqual(_to_sendkeys(\"Ctrl+S\"), \"{Ctrl}s\")\n        self.assertEqual(_to_sendkeys(\"Ctrl+Shift+S\"), \"{Ctrl}{Shift}s\")\n        self.assertEqual(_to_sendkeys(\"Enter\"), \"{Enter}\")\n        self.assertEqual(_to_sendkeys(\"F5\"), \"{F5}\")\n\n    def test_no_win32_shorthand_leaks_through(self):\n        \"\"\"A bare `^`, `+` or `%` would be typed as text, not held.\"\"\"\n        for combo in (\"Ctrl+A\", \"Alt+F4\", \"Ctrl+Shift+N\", \"Win+D\"):\n            seq = _to_sendkeys(combo)\n            self.assertNotIn(\"^\", seq, combo)\n            self.assertFalse(seq.startswith(\"+\"), combo)\n            self.assertNotIn(\"%\", seq, combo)\n\n    def test_cuas_key_names_on_the_python_path(self):\n        \"\"\"fx4 (t1 I4): the names CUA's key table knows (keyboard.rs:811-819,\n        :860-913) are accepted here too, in uiautomation's spelling.\"\"\"\n        self.assertEqual(_to_sendkeys(\"Alt\"), \"{Alt}\")\n        self.assertEqual(_to_sendkeys(\"CapsLock\"), \"{Capital}\")\n        self.assertEqual(_to_sendkeys(\"PgDn\"), \"{PageDown}\")\n        self.assertEqual(_to_sendkeys(\"Ins\"), \"{Insert}\")\n        self.assertEqual(_to_sendkeys(\"Option+F4\"), \"{Alt}{F4}\")\n        self.assertEqual(_to_sendkeys(\"Meta+D\"), \"{Win}d\")\n\n    def test_unknown_key_rejected_with_hint(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            _to_sendkeys(\"Ctrl+NotAKey\")\n        self.assertTrue(ctx.exception.error.hint)\n\n    def test_sendkeys_escaping(self):\n        \"\"\"Unescaped braces become keystrokes instead of text.\"\"\"\n        self.assertEqual(_escape_sendkeys(\"a+b\"), \"a{+}b\")\n        self.assertEqual(_escape_sendkeys(\"50%\"), \"50{%}\")\n        self.assertEqual(_escape_sendkeys(\"{x}\"), \"{{}x{}}\")\n        self.assertEqual(_escape_sendkeys(\"plain\"), \"plain\")\n\n\nclass TestNameCleaning(unittest.TestCase):\n    def test_private_use_glyphs_removed(self):\n        \"\"\"Segoe Fluent icon glyphs render as nothing and mean nothing.\"\"\"\n        self.assertEqual(uia._clean_name(\"\"), \"\")\n        self.assertEqual(uia._clean_name(\"Close \"), \"Close\")\n\n    def test_zero_width_removed(self):\n        self.assertEqual(uia._clean_name(\"a​b\"), \"ab\")\n\n    def test_arabic_preserved(self):\n        self.assertEqual(uia._clean_name('\\u062d\\u0641\\u0638 \\u0627\\u0644\\u0645\\u0644\\u0641'), '\\u062d\\u0641\\u0638 \\u0627\\u0644\\u0645\\u0644\\u0641')\n\n    def test_whitespace_collapsed(self):\n        self.assertEqual(uia._clean_name(\"  a   b  \"), \"a b\")\n\n    def test_long_names_truncated(self):\n        self.assertLessEqual(len(uia._clean_name(\"x\" * 500)), 120)\n\n\nclass TestBrowserPerception(unittest.TestCase):\n    def ax(self, nodes):\n        return nodes\n\n    def test_ignored_wrappers_do_not_discard_their_subtree(self):\n        \"\"\"Regression: Chromium wraps content in ignored role=none nodes.\n\n        Returning early on `ignored` threw the whole page away — example.com\n        yielded 1 ref instead of its heading, paragraph and link.\n        \"\"\"\n        nodes = [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1,\n             \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"T\"},\n             \"childIds\": [\"2\"]},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 2, \"ignored\": True,\n             \"role\": {\"value\": \"none\"}, \"childIds\": [\"3\"]},\n            {\"nodeId\": \"3\", \"backendDOMNodeId\": 3,\n             \"role\": {\"value\": \"link\"}, \"name\": {\"value\": \"Learn more\"},\n             \"childIds\": []},\n        ]\n        snap = {\"documents\": [{\n            \"nodes\": {\"backendNodeId\": [1, 2, 3]},\n            \"layout\": {\"nodeIndex\": [0, 1, 2],\n                       \"bounds\": [[0, 0, 800, 600], [0, 0, 800, 100],\n                                  [10, 10, 100, 20]]}}]}\n        store = perceive.BrowserRefStore()\n        obs = perceive.build(nodes, snap, store, url=\"u\", title=\"T\",\n                             viewport=(800, 600), started=0.0)\n        text = perceive.render(obs)\n        self.assertIn(\"Learn more\", text)\n        self.assertEqual(obs.ref_count, 1)\n\n    def test_geometry_join_by_backend_id(self):\n        snap = {\"documents\": [{\n            \"nodes\": {\"backendNodeId\": [7]},\n            \"layout\": {\"nodeIndex\": [0], \"bounds\": [[5, 6, 100, 50]]}}]}\n        geo = perceive._geometry(snap)\n        self.assertEqual(geo[7], (5.0, 6.0, 100.0, 50.0))\n\n    def test_coverage_detects_full_screen_overlay(self):\n        self.assertAlmostEqual(perceive._coverage((0, 0, 800, 600), 800, 600), 1.0)\n        self.assertAlmostEqual(perceive._coverage((0, 0, 80, 60), 800, 600), 0.01)\n        self.assertEqual(perceive._coverage(None, 800, 600), 0.0)\n\n    def test_password_field_is_detected_and_masked(self):\n        nodes = [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1,\n             \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"T\"},\n             \"childIds\": [\"2\"]},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 2,\n             \"role\": {\"value\": \"textbox\"}, \"name\": {\"value\": \"Password\"},\n             \"value\": {\"value\": \"hunter2\"}, \"childIds\": []},\n        ]\n        snap = {\"documents\": [{\n            \"nodes\": {\"backendNodeId\": [1, 2]},\n            \"layout\": {\"nodeIndex\": [0, 1],\n                       \"bounds\": [[0, 0, 800, 600], [0, 0, 200, 30]]}}]}\n        store = perceive.BrowserRefStore()\n        obs = perceive.build(nodes, snap, store, url=\"u\", title=\"T\",\n                             viewport=(800, 600), started=0.0)\n        text = perceive.render(obs)\n        self.assertNotIn(\"hunter2\", text)\n        self.assertIn(perceive.MASK, text)\n        self.assertTrue(store.get(\"@e1\")[\"sensitive\"])\n\n\nclass TestReaper(unittest.TestCase):\n    \"\"\"Orphan reaping must never touch a process that is not ours.\n\n    The user has dozens of their own Chrome processes. A PID is not identity:\n    PIDs are recycled. Killing the wrong one loses their work.\n    \"\"\"\n\n    def setUp(self):\n        import tempfile\n        self.home = Path(tempfile.mkdtemp(prefix=\"reaper-test-\"))\n        self.profile = self.home / \"browser-profile\"\n\n    def _sleeper(self):\n        import subprocess\n        return subprocess.Popen([sys.executable, \"-c\", \"import time;time.sleep(30)\"])\n\n    def test_refuses_pid_whose_creation_time_differs(self):\n        \"\"\"The PID-reuse guard: same number, different process.\"\"\"\n        import json\n        proc = self._sleeper()\n        try:\n            reaper.register(self.home, browser_pid=proc.pid, bridge_pid=None,\n                            profile=self.profile)\n            rows = json.loads((self.home / \"browsers.json\").read_text())\n            rows[-1][\"browser\"][\"created\"] = 1.0      # as PID reuse would look\n            rows[-1][\"owner_pid\"] = 999_999           # owner is gone\n            (self.home / \"browsers.json\").write_text(json.dumps(rows))\n\n            res = reaper.reap(self.home)\n            self.assertEqual(res[\"reaped\"], 0)\n            self.assertIsNone(proc.poll(), \"an unrelated process was killed\")\n        finally:\n            proc.kill()\n            proc.wait(timeout=5)\n\n    def test_refuses_process_with_wrong_name(self):\n        \"\"\"python.exe is not chrome.exe, whatever the record claims.\"\"\"\n        import json\n        proc = self._sleeper()\n        try:\n            reaper.register(self.home, browser_pid=proc.pid, bridge_pid=None,\n                            profile=self.profile)\n            rows = json.loads((self.home / \"browsers.json\").read_text())\n            rows[-1][\"owner_pid\"] = 999_999\n            (self.home / \"browsers.json\").write_text(json.dumps(rows))\n            reaper.reap(self.home)\n            self.assertIsNone(proc.poll(), \"a non-browser process was killed\")\n        finally:\n            proc.kill()\n            proc.wait(timeout=5)\n\n    def test_record_owned_by_a_live_daemon_is_kept(self):\n        \"\"\"Another running daemon's browser is in active use, not an orphan.\"\"\"\n        import json\n        owner = self._sleeper()\n        try:\n            reaper.register(self.home, browser_pid=424242, bridge_pid=None,\n                            profile=self.profile)\n            rows = json.loads((self.home / \"browsers.json\").read_text())\n            rows[-1][\"owner_pid\"] = owner.pid       # a *different*, live owner\n            (self.home / \"browsers.json\").write_text(json.dumps(rows))\n\n            res = reaper.reap(self.home)\n            self.assertEqual(res[\"reaped\"], 0)\n            kept = json.loads((self.home / \"browsers.json\").read_text())\n            self.assertEqual(len(kept), 1, \"a live owner's record was dropped\")\n        finally:\n            owner.kill()\n            owner.wait(timeout=5)\n\n    def test_unregister_removes_the_record(self):\n        import json\n        reaper.register(self.home, browser_pid=111, bridge_pid=222,\n                        profile=self.profile)\n        reaper.unregister(self.home, 111)\n        self.assertEqual(json.loads((self.home / \"browsers.json\").read_text()), [])\n\n    def test_empty_registry_is_harmless(self):\n        self.assertEqual(reaper.reap(self.home)[\"checked\"], 0)\n\n\nclass TestIframeGeometry(unittest.TestCase):\n    \"\"\"Nested documents must be shifted into top-level page coordinates.\"\"\"\n\n    def test_rare_data_decoding(self):\n        \"\"\"DOMSnapshot optional fields are sparse, not dense arrays.\n\n        Treating `{\"index\": [...], \"value\": [...]}` as a list iterates the dict\n        keys, which produced `'<' not supported between str and int`.\n        \"\"\"\n        self.assertEqual(perceive._rare({\"index\": [2, 5], \"value\": [7, 9]}),\n                         {2: 7, 5: 9})\n        self.assertEqual(perceive._rare([10, 11]), {0: 10, 1: 11})\n        self.assertEqual(perceive._rare(None), {})\n\n    def test_iframe_boxes_are_offset_by_their_host(self):\n        \"\"\"A field inside an iframe must not report the frame's local origin.\"\"\"\n        snap = {\"documents\": [\n            {\"nodes\": {\"backendNodeId\": [1, 2],\n                       \"contentDocumentIndex\": {\"index\": [1], \"value\": [1]}},\n             \"layout\": {\"nodeIndex\": [0, 1],\n                        \"bounds\": [[0, 0, 800, 600], [100, 200, 400, 300]]}},\n            {\"nodes\": {\"backendNodeId\": [9]},\n             \"layout\": {\"nodeIndex\": [0], \"bounds\": [[10, 20, 150, 30]]}},\n        ]}\n        geo = perceive._geometry(snap)\n        # host iframe sits at (100, 200); the inner field is local (10, 20)\n        self.assertEqual(geo[9], (110.0, 220.0, 150.0, 30.0))\n\n    def test_frame_tree_is_stitched_under_its_host(self):\n        main = [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1,\n             \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"Outer\"},\n             \"childIds\": [\"2\"]},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 5,\n             \"role\": {\"value\": \"Iframe\"}, \"name\": {\"value\": \"\"},\n             \"childIds\": []},\n        ]\n        inner = [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 9,\n             \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"Inner\"},\n             \"childIds\": [\"2\"]},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 10,\n             \"role\": {\"value\": \"button\"}, \"name\": {\"value\": \"Pay now\"},\n             \"childIds\": []},\n        ]\n        snap = {\"documents\": [{\n            \"nodes\": {\"backendNodeId\": [1, 5, 9, 10]},\n            \"layout\": {\"nodeIndex\": [0, 1, 2, 3],\n                       \"bounds\": [[0, 0, 800, 600], [0, 100, 400, 200],\n                                  [0, 100, 400, 200], [10, 110, 80, 24]]}}]}\n        store = perceive.BrowserRefStore()\n        obs = perceive.build(main, snap, store, url=\"u\", title=\"Outer\",\n                             viewport=(800, 600), started=0.0,\n                             frame_trees=[(5, inner)])\n        text = perceive.render(obs)\n        self.assertIn(\"Pay now\", text)\n\n\nclass TestDomFacts(unittest.TestCase):\n    \"\"\"Password detection and labelling must come from the DOM, not a guess.\"\"\"\n\n    def snap(self, tag, attrs):\n        strings, idx = [], {}\n        def sid(v):\n            if v not in idx:\n                idx[v] = len(strings); strings.append(v)\n            return idx[v]\n        attr_list = []\n        for k, v in attrs.items():\n            attr_list += [sid(k), sid(v)]\n        return {\"strings\": strings,\n                \"documents\": [{\"nodes\": {\"backendNodeId\": [42],\n                                         \"nodeName\": [sid(tag)],\n                                         \"attributes\": [attr_list]},\n                               \"layout\": {\"nodeIndex\": [], \"bounds\": []}}]}\n\n    def test_password_input_detected_without_any_label(self):\n        \"\"\"The case that was both invisible and unprotected.\"\"\"\n        facts = perceive.dom_facts(self.snap(\"INPUT\", {\"type\": \"password\"}))\n        self.assertTrue(perceive.is_password_node(facts[42]))\n\n    def test_autocomplete_password_detected(self):\n        facts = perceive.dom_facts(\n            self.snap(\"INPUT\", {\"type\": \"text\", \"autocomplete\": \"current-password\"}))\n        self.assertTrue(perceive.is_password_node(facts[42]))\n\n    def test_ordinary_text_input_is_not_a_password(self):\n        facts = perceive.dom_facts(self.snap(\"INPUT\", {\"type\": \"text\"}))\n        self.assertFalse(perceive.is_password_node(facts[42]))\n\n    def test_unnamed_control_gets_a_usable_label(self):\n        facts = perceive.dom_facts(\n            self.snap(\"INPUT\", {\"type\": \"email\", \"placeholder\": \"Work email\"}))\n        self.assertEqual(perceive.describe_unnamed(facts[42], \"textbox\"),\n                         \"Work email\")\n\n    def test_label_of_last_resort_names_the_type(self):\n        facts = perceive.dom_facts(self.snap(\"INPUT\", {\"type\": \"password\"}))\n        self.assertIn(\"password\", perceive.describe_unnamed(facts[42], \"textbox\"))\n\n    def test_unnamed_interactive_element_still_gets_a_ref(self):\n        \"\"\"Dropping it made the element unusable *and* unprotected.\"\"\"\n        nodes = [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1,\n             \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"T\"},\n             \"childIds\": [\"2\"]},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 42,\n             \"role\": {\"value\": \"textbox\"}, \"name\": {\"value\": \"\"},\n             \"childIds\": []},\n        ]\n        snap = self.snap(\"INPUT\", {\"type\": \"password\"})\n        snap[\"documents\"][0][\"nodes\"][\"backendNodeId\"] = [1, 42]\n        snap[\"documents\"][0][\"nodes\"][\"nodeName\"] = [0, 0]\n        snap[\"documents\"][0][\"nodes\"][\"attributes\"] = [[], snap[\"documents\"][0][\"nodes\"][\"attributes\"][0]]\n        snap[\"documents\"][0][\"layout\"] = {\"nodeIndex\": [0, 1],\n                                          \"bounds\": [[0, 0, 800, 600], [0, 0, 200, 30]]}\n        store = perceive.BrowserRefStore()\n        obs = perceive.build(nodes, snap, store, url=\"u\", title=\"T\",\n                             viewport=(800, 600), started=0.0)\n        self.assertEqual(obs.ref_count, 1)\n        self.assertTrue(store.get(\"@e1\")[\"sensitive\"])\n\n\nclass TestOnScreenGuard(unittest.TestCase):\n    \"\"\"A desktop click moves the real mouse; an off-screen point is unsafe.\"\"\"\n\n    def _entry(self):\n        from autoskill.desktop.refs import ElementRef\n        return ElementRef(ref=\"@e1\", control=None, role=\"button\", name=\"OK\",\n                          generation=1)\n\n    def test_rejects_minimised_window_coordinates(self):\n        from autoskill.desktop.actions import _require_on_screen\n        with self.assertRaises(ProtocolError) as ctx:\n            _require_on_screen(-31280, -31564, self._entry())\n        self.assertEqual(ctx.exception.error.code, ErrorCode.TARGET_NOT_VISIBLE)\n        self.assertEqual(ctx.exception.error.effect_state, EffectState.NONE)\n        self.assertTrue(ctx.exception.error.hint)\n\n    def test_accepts_a_normal_point(self):\n        from autoskill.desktop.actions import _require_on_screen\n        _require_on_screen(100, 100, self._entry())   # must not raise\n\n\nclass TestUiaExecutor(unittest.TestCase):\n    \"\"\"UIA is COM: one apartment, one thread, no cross-thread object use.\"\"\"\n\n    def test_all_work_lands_on_one_thread(self):\n        \"\"\"Found in real use as `CoInitialize has not been called`.\n\n        The daemon serves each connection on a new thread. Only the importing\n        thread had a COM apartment, and UIA objects held in the ref store were\n        being called from whichever thread arrived next — undefined behaviour,\n        not merely an error.\n        \"\"\"\n        import threading\n        from autoskill.desktop.executor import uia_call\n        seen = set()\n\n        def collect():\n            return threading.get_ident()\n\n        for _ in range(12):\n            seen.add(uia_call(collect, timeout=30))\n        self.assertEqual(len(seen), 1, \"UIA work ran on more than one thread\")\n\n    def test_worker_thread_is_not_the_caller(self):\n        import threading\n        from autoskill.desktop.executor import uia_call\n        worker = uia_call(lambda: threading.get_ident(), timeout=30)\n        self.assertNotEqual(worker, threading.get_ident())\n\n    def test_exceptions_cross_the_boundary_unchanged(self):\n        from autoskill.desktop.executor import uia_call\n        def boom():\n            raise ProtocolError(ErrorCode.TARGET_DISABLED, \"nope\", hint=\"h\")\n        with self.assertRaises(ProtocolError) as ctx:\n            uia_call(boom, timeout=30)\n        self.assertEqual(ctx.exception.error.code, ErrorCode.TARGET_DISABLED)\n        self.assertEqual(ctx.exception.error.hint, \"h\")\n\n    def test_calls_from_many_threads_are_serialised(self):\n        import threading\n        from autoskill.desktop.executor import uia_call\n        order, lock = [], threading.Lock()\n\n        def work(n):\n            def inner():\n                with lock:\n                    order.append(n)\n                return n\n            return uia_call(inner, timeout=30)\n\n        threads = [threading.Thread(target=work, args=(i,)) for i in range(8)]\n        for t in threads:\n            t.start()\n        for t in threads:\n            t.join(timeout=30)\n        self.assertEqual(sorted(order), list(range(8)))\n\n\nclass TestScrollContract(unittest.TestCase):\n    \"\"\"Scrolling must move only the axis asked for, and prove it moved.\"\"\"\n\n    class FakeConn:\n        \"\"\"Minimal CDP stand-in that records what was dispatched.\"\"\"\n\n        def __init__(self, pos=(0, 0)):\n            self.pos = list(pos)\n            self.wheel = None\n\n        def send(self, method, params=None, *, session_id=None, timeout=0):\n            params = params or {}\n            if method == \"Runtime.evaluate\":\n                expr = params.get(\"expression\", \"\")\n                if \"scrollX\" in expr:\n                    return {\"result\": {\"value\": f\"{self.pos[0]},{self.pos[1]}\"}}\n                return {\"result\": {\"value\": json.dumps(\n                    {\"u\": \"u\", \"t\": \"t\", \"w\": 800, \"h\": 600})}}\n            if method == \"Input.dispatchMouseEvent\":\n                self.wheel = (params.get(\"deltaX\", 0), params.get(\"deltaY\", 0))\n                self.pos[0] += self.wheel[0]\n                self.pos[1] += self.wheel[1]\n            return {}\n\n    def page(self, pos=(0, 0)):\n        from autoskill.browser.page import Page\n        conn = self.FakeConn(pos)\n        pg = Page.__new__(Page)\n        pg.conn, pg.session_id = conn, \"s\"\n        return pg, conn\n\n    def test_horizontal_scroll_does_not_move_vertically(self):\n        \"\"\"`--delta-x` used to also apply the 400px default `delta_y`.\"\"\"\n        pg, conn = self.page()\n        res = pg.scroll(delta_x=800)\n        self.assertEqual(conn.wheel, (800, 0))\n        self.assertEqual(res[\"moved\"], {\"x\": 800, \"y\": 0})\n\n    def test_vertical_scroll_does_not_move_horizontally(self):\n        pg, conn = self.page()\n        res = pg.scroll(delta_y=-200)\n        self.assertEqual(conn.wheel, (0, -200))\n        self.assertEqual(res[\"moved\"], {\"x\": 0, \"y\": -200})\n\n    def test_bare_scroll_still_means_down(self):\n        pg, conn = self.page()\n        pg.scroll()\n        self.assertEqual(conn.wheel, (0, 400))\n\n    def test_zero_delta_is_rejected(self):\n        pg, _ = self.page()\n        with self.assertRaises(ProtocolError) as ctx:\n            pg.scroll(delta_x=0, delta_y=0)\n        self.assertTrue(ctx.exception.error.hint)\n\n    def test_all_four_directions_are_expressible(self):\n        for dx, dy, expect in ((0, 400, \"down\"), (0, -400, \"up\"),\n                               (400, 0, \"right\"), (-400, 0, \"left\")):\n            pg, conn = self.page()\n            pg.scroll(delta_x=dx or None, delta_y=dy or None)\n            self.assertEqual(conn.wheel, (dx, dy), f\"{expect} misdispatched\")\n\n    def test_no_movement_is_reported_as_none_not_committed(self):\n        \"\"\"A page at its limit must not look like a successful scroll.\"\"\"\n        class Stuck(self.FakeConn):\n            def send(self, method, params=None, *, session_id=None, timeout=0):\n                if method == \"Input.dispatchMouseEvent\":\n                    return {}          # accepted, but nothing moves\n                return super().send(method, params, session_id=session_id,\n                                    timeout=timeout)\n        from autoskill.browser.page import Page\n        pg = Page.__new__(Page)\n        pg.conn, pg.session_id = Stuck(), \"s\"\n        res = pg.scroll(delta_y=600)\n        self.assertEqual(res[\"effect_state\"], EffectState.NONE.value)\n        self.assertIn(\"nothing moved\", res[\"note\"])\n\n\nclass TestDialogHandling(unittest.TestCase):\n    \"\"\"A blocking JS dialog must be answered and reported, never ignored.\n\n    Measured before the fix: one `alert()` made `click` time out at 20s and\n    then wedged the session permanently - every later call timed out, because\n    the renderer was blocked and the reply could never arrive.\n    \"\"\"\n\n    def page(self, policy=\"dismiss\"):\n        from autoskill.browser.page import Page\n        pg = Page.__new__(Page)\n        pg.session_id = \"s\"\n        pg.dialog_policy = policy\n        pg._dialogs, pg._console = [], []\n        pg._dialog_lock = __import__(\"threading\").Lock()\n        posted = []\n\n        class C:\n            def post(self, method, params=None, *, session_id=None):\n                posted.append((method, params))\n                return True\n        pg.conn = C()\n        return pg, posted\n\n    def test_dialog_is_answered_immediately(self):\n        pg, posted = self.page()\n        pg._on_event(\"Page.javascriptDialogOpening\",\n                     {\"type\": \"alert\", \"message\": \"hi\", \"url\": \"u\"}, \"s\")\n        self.assertEqual(posted[0][0], \"Page.handleJavaScriptDialog\")\n        self.assertFalse(posted[0][1][\"accept\"])\n\n    def test_accept_policy_is_honoured(self):\n        pg, posted = self.page(\"accept\")\n        pg._on_event(\"Page.javascriptDialogOpening\",\n                     {\"type\": \"confirm\", \"message\": \"ok?\"}, \"s\")\n        self.assertTrue(posted[0][1][\"accept\"])\n\n    def test_answer_is_posted_not_sent(self):\n        \"\"\"`send()` from the reader thread deadlocks against itself.\"\"\"\n        pg, _ = self.page()\n        self.assertFalse(hasattr(pg.conn, \"send\"))   # only post() is used\n\n    def test_dialog_is_reported_on_the_triggering_action(self):\n        pg, _ = self.page()\n        pg._on_event(\"Page.javascriptDialogOpening\",\n                     {\"type\": \"alert\", \"message\": \"blocking alert\"}, \"s\")\n        out = pg._with_dialogs({\"effect_state\": \"committed\"})\n        self.assertEqual(len(out[\"dialogs\"]), 1)\n        self.assertIn(\"blocking alert\", out[\"note\"])\n\n    def test_dialogs_are_drained_not_repeated(self):\n        pg, _ = self.page()\n        pg._on_event(\"Page.javascriptDialogOpening\", {\"type\": \"alert\"}, \"s\")\n        pg._with_dialogs({})\n        self.assertNotIn(\"dialogs\", pg._with_dialogs({}))\n\n    def test_events_for_other_sessions_are_ignored(self):\n        pg, posted = self.page()\n        pg._on_event(\"Page.javascriptDialogOpening\", {\"type\": \"alert\"}, \"other\")\n        self.assertEqual(posted, [])\n\n    def test_console_entries_are_captured(self):\n        pg, _ = self.page()\n        pg._on_event(\"Log.entryAdded\",\n                     {\"entry\": {\"level\": \"error\", \"text\": \"boom\"}}, \"s\")\n        self.assertEqual(pg._console[0][\"level\"], \"error\")\n\n\nclass TestHoverMarkers(unittest.TestCase):\n    \"\"\"Hover-only menus are invisible without a marker to find the trigger.\"\"\"\n\n    def test_aria_haspopup_becomes_a_has_submenu_marker(self):\n        nodes = [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1,\n             \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"T\"},\n             \"childIds\": [\"2\"]},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 7,\n             \"role\": {\"value\": \"button\"}, \"name\": {\"value\": \"Products\"},\n             \"childIds\": []},\n        ]\n        strings = [\"BUTTON\", \"aria-haspopup\", \"menu\"]\n        snap = {\"strings\": strings,\n                \"documents\": [{\"nodes\": {\"backendNodeId\": [1, 7],\n                                         \"nodeName\": [0, 0],\n                                         \"attributes\": [[], [1, 2]]},\n                               \"layout\": {\"nodeIndex\": [0, 1],\n                                          \"bounds\": [[0, 0, 800, 600],\n                                                     [10, 10, 90, 30]]}}]}\n        store = perceive.BrowserRefStore()\n        obs = perceive.build(nodes, snap, store, url=\"u\", title=\"T\",\n                             viewport=(800, 600), started=0.0)\n        self.assertIn(\"[has-submenu]\", perceive.render(obs))\n\n\nclass TestActionability(unittest.TestCase):\n    \"\"\"Four checks, each guarding a measured false success.\"\"\"\n\n    def probe(self, value):\n        from autoskill.browser import actionable\n\n        class C:\n            def send(self, method, params=None, *, session_id=None, timeout=0):\n                if method == \"DOM.resolveNode\":\n                    return {\"object\": {\"objectId\": \"o1\"}}\n                return {\"result\": {\"value\": value}}\n        return actionable, C()\n\n    def test_obscured_element_is_refused_and_names_the_blocker(self):\n        \"\"\"Measured: a button behind a cookie wall reported `committed`.\"\"\"\n        act, conn = self.probe(\n            {\"ok\": False, \"reason\": \"obscured\", \"obscured_by\": \"div#cookie\",\n             \"rect\": {\"x\": 1, \"y\": 1, \"w\": 10, \"h\": 10}})\n        with self.assertRaises(ProtocolError) as ctx:\n            act.ensure_actionable(conn, \"s\", 1, \"@e2\", \"button 'Buy'\", timeout=0.1)\n        self.assertIn(\"obscured\", ctx.exception.error.message)\n        self.assertIn(\"div#cookie\", ctx.exception.error.message)\n\n    def test_moving_element_is_refused(self):\n        act, conn = self.probe({\"ok\": False, \"reason\": \"moving\", \"moved\": 70,\n                                \"rect\": {\"x\": 1, \"y\": 1, \"w\": 10, \"h\": 10}})\n        with self.assertRaises(ProtocolError) as ctx:\n            act.ensure_actionable(conn, \"s\", 1, \"@e3\", \"button\", timeout=0.1)\n        self.assertIn(\"moving\", ctx.exception.error.message)\n\n    def test_refusal_reports_effect_state_none(self):\n        \"\"\"Nothing was dispatched, so retrying is safe - say so.\"\"\"\n        act, conn = self.probe({\"ok\": False, \"reason\": \"disabled\"})\n        with self.assertRaises(ProtocolError) as ctx:\n            act.ensure_actionable(conn, \"s\", 1, \"@e1\", \"button\", timeout=0.1)\n        self.assertEqual(ctx.exception.error.effect_state, EffectState.NONE)\n\n    def test_actionable_element_returns_its_point(self):\n        act, conn = self.probe({\"ok\": True, \"x\": 42.0, \"y\": 24.0})\n        got = act.ensure_actionable(conn, \"s\", 1, \"@e1\", \"button\", timeout=1)\n        self.assertEqual((got[\"x\"], got[\"y\"]), (42.0, 24.0))\n\n    def test_detached_node_is_a_stale_ref(self):\n        from autoskill.browser import actionable\n\n        class C:\n            def send(self, method, params=None, *, session_id=None, timeout=0):\n                return {\"object\": {}}          # no objectId\n        with self.assertRaises(ProtocolError) as ctx:\n            actionable.ensure_actionable(C(), \"s\", 1, \"@e9\", \"button\", timeout=1)\n        self.assertEqual(ctx.exception.error.code, ErrorCode.STALE_REF)\n\n    def test_non_transient_reasons_do_not_wait(self):\n        \"\"\"`disabled` will not fix itself; failing fast beats a 5s stall.\"\"\"\n        from autoskill.browser import actionable\n        self.assertNotIn(\"disabled\", actionable.TRANSIENT)\n        self.assertIn(\"obscured\", actionable.TRANSIENT)\n        self.assertIn(\"moving\", actionable.TRANSIENT)\n\n    def test_every_reason_has_a_hint(self):\n        from autoskill.browser import actionable\n        for reason in actionable.TRANSIENT | {\"disabled\", \"detached\"}:\n            self.assertIn(reason, actionable.HINTS, f\"{reason} has no hint\")\n\n\nclass TestProtocol(unittest.TestCase):\n    def test_request_roundtrip(self):\n        r = Request(method=\"desktop.click\", params={\"ref\": \"@e1\"}, session=\"ab12\")\n        back = Request.from_line(r.to_line())\n        self.assertEqual(back.method, \"desktop.click\")\n        self.assertEqual(back.session, \"ab12\")\n\n    def test_error_response_carries_effect_state(self):\n        exc = ProtocolError(ErrorCode.TIMEOUT, \"no reply\",\n                            effect_state=EffectState.UNKNOWN)\n        resp = Response.failure(\"id\", exc.error, 0.0)\n        self.assertFalse(resp.ok)\n        self.assertEqual(resp.error[\"effect_state\"], \"unknown\")\n\n    def test_default_effect_state_is_none(self):\n        exc = ProtocolError(ErrorCode.UNKNOWN_REF, \"nope\")\n        self.assertEqual(exc.error.effect_state, EffectState.NONE)\n\n\nclass TestLegacyPolicyFields(unittest.TestCase):\n    \"\"\"Owner decision 2026-10-11 removed the URL deny list (CUA-aligned).\n    URLs never refuse; old policy files still load with their legacy\n    deny/url_deny/allow fields, inert.\"\"\"\n\n    def test_urls_never_refuse_after_cua_realignment(self):\n        for mode in PermissionMode:\n            d = PermissionEngine(PermissionPolicy(mode=mode)).check(\n                \"browser.navigate\", url=\"https://www.paypal.com/signin\")\n            self.assertTrue(d.allowed, f\"url refused in {mode.value}\")\n\n    def test_legacy_policy_fields_load_inert(self):\n        saved = PermissionPolicy().to_dict()\n        saved[\"deny\"] = [\"*keepass*\"]\n        saved[\"url_deny\"] = [\"*paypal.com*\"]\n        p = PermissionPolicy.from_dict(saved)\n        self.assertEqual(p.deny, [\"*keepass*\"])\n        self.assertEqual(p.url_deny, [\"*paypal.com*\"])\n        d = PermissionEngine(p).check(\"desktop.click\", process=\"KeePass.exe\")\n        self.assertTrue(d.allowed)\n\n\nclass TestObservationContinuation(unittest.TestCase):\n    \"\"\"`@more` hands out the rest of a budgeted observation without\n    re-observing, which would invalidate every ref just issued.\"\"\"\n\n    class FakeConn:\n        def __init__(self, n_links=30):\n            links = [{\"nodeId\": str(i + 2), \"backendDOMNodeId\": i + 2,\n                      \"role\": {\"value\": \"link\"},\n                      \"name\": {\"value\": f\"link number {i}\"},\n                      \"childIds\": [str(i + 3)]}\n                     for i in range(n_links)]\n            links[-1][\"childIds\"] = []\n            self.nodes = [\n                {\"nodeId\": \"1\", \"backendDOMNodeId\": 1,\n                 \"role\": {\"value\": \"RootWebArea\"}, \"name\": {\"value\": \"T\"},\n                 \"childIds\": [\"2\"]}] + links\n            self.subscriptions = []\n\n        def subscribe(self, cb):\n            self.subscriptions.append(cb)\n\n        def send(self, method, params=None, *, session_id=None, timeout=0):\n            if method == \"Accessibility.getFullAXTree\":\n                return {\"nodes\": self.nodes}\n            if method == \"DOMSnapshot.captureSnapshot\":\n                n = len(self.nodes)\n                return {\"documents\": [{\n                    \"nodes\": {\"backendNodeId\": list(range(1, n + 1))},\n                    \"layout\": {\"nodeIndex\": list(range(n)),\n                               \"bounds\": [[10, 10 * i, 200, 20]\n                                          for i in range(n)]}}]}\n            if method == \"Page.getFrameTree\":\n                return {\"frameTree\": {\"frame\": {\"id\": \"f\"}}}\n            if method == \"Runtime.evaluate\":\n                expr = params.get(\"expression\", \"\")\n                if \"readyState\" in expr:\n                    return {\"result\": {\"value\": \"complete\"}}\n                return {\"result\": {\"value\": json.dumps(\n                    {\"u\": \"https://example.test/page\", \"t\": \"T\",\n                     \"w\": 800, \"h\": 600})}}\n            return {}\n\n    def page(self, n_links=30):\n        from autoskill.browser.page import Page\n        return Page(self.FakeConn(n_links), \"target-1\", \"s\")\n\n    def test_budgeted_observe_reports_a_cursor(self):\n        pg = self.page()\n        out = pg.observe(max_tokens=2)          # ~7 chars: the header only\n        self.assertIn(\"@more cursor=\", out[\"text\"])\n        self.assertGreater(out.get(\"truncated_lines\", 0), 0)\n        self.assertTrue(out[\"cursor\"])\n\n    def test_more_returns_the_following_lines(self):\n        pg = self.page()\n        out = pg.observe(max_tokens=2)\n        cut = out[\"cursor\"]\n        rest = pg.more(cut, max_tokens=50)\n        self.assertIn(\"link number\", rest[\"text\"])\n        self.assertEqual(rest[\"from_line\"], cut)\n\n    def test_continuation_runs_to_an_end_marker(self):\n        pg = self.page(n_links=5)\n        out = pg.observe(max_tokens=2)\n        seen_end = False\n        cursor = out.get(\"cursor\")\n        for _ in range(50):                     # hard bound, not a real loop\n            if cursor is None:\n                seen_end = True\n                break\n            chunk = pg.more(cursor, max_tokens=2)\n            if \"@end of observation\" in chunk[\"text\"]:\n                seen_end = True\n                break\n            cursor = chunk.get(\"cursor\")\n        self.assertTrue(seen_end)\n\n    def test_more_refuses_when_the_page_changed(self):\n        pg = self.page()\n        out = pg.observe(max_tokens=2)\n        pg.refs.begin()                          # any later observe/navigate\n        with self.assertRaises(ProtocolError) as ctx:\n            pg.more(out[\"cursor\"], max_tokens=2)\n        self.assertEqual(ctx.exception.error.code, ErrorCode.STALE_REF)\n\n    def test_more_without_a_budgeted_observe_is_unsupported(self):\n        pg = self.page()\n        with self.assertRaises(ProtocolError) as ctx:\n            pg.more(None)\n        self.assertEqual(ctx.exception.error.code, ErrorCode.UNSUPPORTED)\n        self.assertTrue(ctx.exception.error.hint)\n\n    def test_continuation_survives_across_chunks_without_new_refs(self):\n        \"\"\"Reading more must not invalidate the refs observe just issued.\"\"\"\n        pg = self.page()\n        out = pg.observe(max_tokens=2)\n        gen = pg.refs.generation\n        pg.more(out[\"cursor\"], max_tokens=2)\n        self.assertEqual(pg.refs.generation, gen)\n\n\nclass TestTabSelection(unittest.TestCase):\n    \"\"\"`--tab-id` picks the page a verb acts on; an unknown id must fail with\n    the open tabs listed, never fall back to the active tab silently.\"\"\"\n\n    def session_with_tabs(self):\n        from autoskill.daemon import Session\n\n        class FakePage:\n            def __init__(self, name):\n                self.name = name\n        s = Session(id=\"ab12\")\n        s.browser_pages = {\"t1\": FakePage(\"one\"), \"t2\": FakePage(\"two\")}\n        s.browser_page = s.browser_pages[\"t2\"]\n        return s\n\n    def test_tab_id_selects_that_page(self):\n        from autoskill.handlers import _page_t\n        s = self.session_with_tabs()\n        self.assertEqual(_page_t(s, {\"tab_id\": \"t1\"}).name, \"one\")\n\n    def test_no_tab_id_uses_the_active_page(self):\n        from autoskill.handlers import _page_t\n        s = self.session_with_tabs()\n        self.assertEqual(_page_t(s, {}).name, \"two\")\n\n    def test_unknown_tab_lists_what_is_open(self):\n        from autoskill.handlers import _page_t\n        s = self.session_with_tabs()\n        with self.assertRaises(ProtocolError) as ctx:\n            _page_t(s, {\"tab_id\": \"t9\"})\n        self.assertEqual(ctx.exception.error.code, ErrorCode.UNKNOWN_REF)\n        self.assertIn(\"t1\", ctx.exception.error.hint)\n        self.assertIn(\"t2\", ctx.exception.error.hint)\n\n\nclass FakeControl:\n    \"\"\"Just enough UIA surface for extract_text: reads never raise.\"\"\"\n\n    def __init__(self, name=\"\", control_type=\"TextControl\", children=None,\n                 password=False, value=None, document=None):\n        self.Name = name\n        self.ControlTypeName = control_type\n        self.IsPassword = password\n        self._children = children or []\n        self._value = value\n        self._document = document\n\n    def GetChildren(self):\n        return self._children\n\n    def GetTextPattern(self):\n        if self._document is None:\n            raise AttributeError(\"no text pattern\")\n        text = self._document\n\n        class Range:\n            def GetText(self, n):\n                return text\n        pattern = Range()          # the pattern's DocumentRange, UIA-shaped\n        pattern.DocumentRange = pattern\n        return pattern\n\n    def GetValuePattern(self):\n        if self._value is None:\n            raise AttributeError(\"no value pattern\")\n\n        class VP:\n            Value = self._value\n        return VP()\n\n\nclass TestDesktopExtract(unittest.TestCase):\n    def test_document_paragraphs_come_out_as_lines(self):\n        doc = FakeControl(control_type=\"DocumentControl\",\n                          document=\"First line\\r\\nSecond line\\r\\n\\r\\nThird\")\n        out = uia.extract_text(doc)\n        self.assertIn(\"First line\", out[\"text\"])\n        self.assertIn(\"Third\", out[\"text\"])\n        self.assertEqual(out[\"effect_state\"], \"none\")\n\n    def test_password_values_are_surfaced_after_cua_realignment(self):\n        \"\"\"Owner decision 2026-10-11: the desktop surfaces field values\n        verbatim, password fields included (CUA Windows behaviour).\"\"\"\n        root = FakeControl(children=[\n            FakeControl(name=\"Username\", control_type=\"EditControl\",\n                        value=\"amal\"),\n            FakeControl(name=\"Password\", control_type=\"EditControl\",\n                        password=True, value=\"hunter2\"),\n        ])\n        out = uia.extract_text(root)\n        self.assertIn(\"Username: amal\", out[\"text\"])\n        self.assertIn(\"Password: hunter2\", out[\"text\"])\n\n    def test_consecutive_duplicates_are_collapsed(self):\n        root = FakeControl(children=[\n            FakeControl(name=\"Total\"),\n            FakeControl(name=\"Total\"),\n            FakeControl(name=\"Total\"),\n        ])\n        out = uia.extract_text(root)\n        self.assertEqual(out[\"text\"].count(\"Total\"), 1)\n\n    def test_char_budget_truncates_honestly(self):\n        root = FakeControl(children=[\n            FakeControl(name=f\"row {i} \" + \"x\" * 50) for i in range(100)])\n        out = uia.extract_text(root, max_chars=500)\n        self.assertTrue(out[\"truncated\"])\n        self.assertLessEqual(out[\"chars\"], 510)\n\n\nclass TestRealClick(unittest.TestCase):\n    \"\"\"R26: Win11 dialogs honour a real mouse event and ignore UIA Invoke.\n\n    `click --real` must skip the pattern phase entirely, so an Invoke-capable\n    button receives a coordinate click instead.\n    \"\"\"\n\n    class InvokeButton:\n        \"\"\"A control that *would* accept Invoke — a trap for the old path.\"\"\"\n\n        ControlTypeName = \"ButtonControl\"\n        Name = \"Save\"\n\n        class _Invoke:\n            def Invoke(self):\n                raise AssertionError(\n                    \"pattern phase must be skipped when real=True\")\n\n        def GetInvokePattern(self):\n            return self._Invoke()\n\n        def ScrollIntoView(self):\n            pass\n\n        class _Rect:\n            left, top, right, bottom = 100, 100, 200, 140\n\n        BoundingRectangle = _Rect()\n\n        clicked_at = None\n\n        def Click(self, waitTime=0):\n            type(self).clicked_at = \"real\"\n            return True\n\n    def _click(self, **kw):\n        from autoskill.desktop import actions\n        from autoskill.desktop.refs import RefStore, ElementRef\n        store = RefStore()\n        store.begin_observation()\n        btn = self.InvokeButton()\n        # A windowless element inside an observed window (CM-47).\n        store.add(btn, role=\"button\", name=\"Save\", top_window=7)\n        ref = next(iter(store._map))\n        entry = store.resolve(ref)\n        entry.control = btn\n        # Coordinate clicks go through uiautomation's real mouse; stub the\n        # screen-bounds guard so the test stays headless. A physical click first\n        # raises its owning window: resolve it to a fake and record the raise.\n        actions._require_on_screen = lambda x, y, e: None\n        self.raised = []\n        from unittest.mock import patch\n        with patch.object(actions, \"find_window\", lambda sel: object() if sel == \"#7\" else None), \\\n                patch.object(actions, \"_raise_and_verify\",\n                             lambda w, sel, attempts=3: self.raised.append(sel)):\n            return actions.click(store, ref, **kw)\n\n    def test_real_skips_the_pattern_phase(self):\n        res = self._click(real=True)\n        self.assertEqual(res[\"method\"], \"coordinate\")\n        self.assertEqual(self.InvokeButton.clicked_at, \"real\")\n        self.assertEqual(self.raised, [\"#7\"])        # the observed window, not #0\n\n    def test_parser_accepts_real(self):\n        from autoskill.cli import build_parser\n        args = build_parser().parse_args([\"click\", \"@e1\", \"--real\"])\n        self.assertTrue(args.real)\n\n\nclass TestBrowserChoice(unittest.TestCase):\n    \"\"\"Which browser automation drives is the user's standing decision:\n    explicit --browser wins, then the pinned default, then preference.\"\"\"\n\n    def _daemon_stub(self, default=None):\n        from types import SimpleNamespace\n        return SimpleNamespace(policy=SimpleNamespace(\n            default_browser=default))\n\n    def test_explicit_choice_beats_the_pinned_default(self):\n        from autoskill.handlers import _browser_choice\n        which, source = _browser_choice({\"browser\": \"edge\"},\n                                        self._daemon_stub(\"brave\"))\n        self.assertEqual((which, source), (\"edge\", \"explicit\"))\n\n    def test_pinned_default_used_when_no_explicit_choice(self):\n        from autoskill.handlers import _browser_choice\n        which, source = _browser_choice({}, self._daemon_stub(\"edge\"))\n        self.assertEqual((which, source), (\"edge\", \"default\"))\n\n    def test_falls_back_to_preference_when_nothing_is_set(self):\n        from autoskill.handlers import _browser_choice\n        which, source = _browser_choice({}, self._daemon_stub(None))\n        self.assertEqual((which, source), (None, \"preference\"))\n\n    def test_profile_key_is_short_for_a_full_path(self):\n        from autoskill.handlers import _profile_key\n        self.assertEqual(_profile_key(\"edge\"), \"edge\")\n        self.assertEqual(\n            _profile_key(r\"C:\\Program Files\\Microsoft\\Edge\\Application\"\n                         r\"\\msedge.exe\"), \"msedge\")\n        self.assertEqual(_profile_key(None), \"\")\n\n    def test_policy_roundtrips_the_default_browser(self):\n        p = PermissionPolicy(default_browser=\"edge\")\n        self.assertEqual(PermissionPolicy.from_dict(p.to_dict()).default_browser,\n                         \"edge\")\n        self.assertIsNone(\n            PermissionPolicy.from_dict(PermissionPolicy().to_dict())\n            .default_browser)\n\n    def test_parser_accepts_config_set_default_browser(self):\n        from autoskill.cli import build_parser\n        args = build_parser().parse_args(\n            [\"config\", \"set\", \"default-browser\", \"edge\"])\n        self.assertEqual((args.key, args.value), (\"default-browser\", \"edge\"))\n\n\nclass TestRealBrowserBridge(unittest.TestCase):\n    \"\"\"The own-extension route into the user's signed-in browser.\"\"\"\n\n    def test_native_framing_roundtrip(self):\n        \"\"\"Chrome speaks 4-byte little-endian length + UTF-8 JSON, both ways.\"\"\"\n        import io\n        import struct\n        from autoskill.nmhost import nm_read, nm_write\n\n        buf = io.BytesIO()\n        nm_write(buf, {\"op\": \"ping\", \"id\": 7})\n        buf.seek(0)\n        back = nm_read(buf)\n        self.assertEqual(back, {\"op\": \"ping\", \"id\": 7})\n        buf.seek(0)\n        raw = buf.read()\n        (n,) = struct.unpack(\"<I\", raw[:4])\n        self.assertEqual(n, len(raw) - 4)\n\n    def test_empty_and_broken_streams(self):\n        import io\n        from autoskill.nmhost import nm_read\n        self.assertIsNone(nm_read(io.BytesIO(b\"\")))\n        self.assertEqual(nm_read(io.BytesIO(b\"\\x00\\x00\\x00\\x00\")), {})\n\n    def test_render_observation_assigns_refs_to_named_interactive_nodes(self):\n        from autoskill.nmhost import render_observation\n        ax = {\"nodes\": [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1, \"role\": \"RootWebArea\",\n             \"name\": \"Inbox\", \"value\": None, \"childIds\": [\"2\", \"3\"],\n             \"props\": {}},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 5, \"role\": \"button\",\n             \"name\": \"Compose\", \"value\": None, \"childIds\": [],\n             \"props\": {\"haspopup\": True}},\n            {\"nodeId\": \"3\", \"backendDOMNodeId\": 6, \"role\": \"textbox\",\n             \"name\": \"Search mail\", \"value\": \"\", \"childIds\": [],\n             \"props\": {}},\n        ]}\n        boxes = {\"boxes\": {\"5\": [10, 10, 90, 30], \"6\": [0, 60, 200, 28]}}\n        out = render_observation(ax, boxes)\n        self.assertIn(\"@e1 button \\\"Compose\\\" [has-submenu]\", out[\"text\"])\n        self.assertIn(\"@e2 textbox \\\"Search mail\\\"\", out[\"text\"])\n        self.assertEqual(out[\"refs\"][\"@e1\"][\"backend\"], 5)\n        self.assertEqual(out[\"refs\"][\"@e2\"][\"name\"], \"Search mail\")\n\n    def test_password_like_values_are_never_rendered(self):\n        from autoskill.nmhost import render_observation\n        ax = {\"nodes\": [\n            {\"nodeId\": \"1\", \"backendDOMNodeId\": 1, \"role\": \"RootWebArea\",\n             \"name\": \"T\", \"value\": None, \"childIds\": [\"2\"], \"props\": {}},\n            {\"nodeId\": \"2\", \"backendDOMNodeId\": 9, \"role\": \"textbox\",\n             \"name\": \"Password\", \"value\": \"hunter2\", \"childIds\": [],\n             \"props\": {\"roledescription\": \"password\"}},\n        ]}\n        out = render_observation(ax, {\"boxes\": {\"9\": [0, 0, 80, 20]}})\n        self.assertNotIn(\"hunter2\", out[\"text\"])\n\n    def test_parser_accepts_rb_commands(self):\n        from autoskill.cli import build_parser\n        p = build_parser()\n        self.assertTrue(p.parse_args([\"rb\", \"status\"]).rbsub == \"status\")\n        a = p.parse_args([\"rb\", \"click\", \"@e3\", \"--tab-id\", \"42\"])\n        self.assertEqual((a.ref, a.tab_id), (\"@e3\", 42))\n        b = p.parse_args([\"rb\", \"install\", \"abcdefghijklmnopqrstuv\"])\n        self.assertEqual(b.extension_id, \"abcdefghijklmnopqrstuv\")\n\n\nclass LyingEditControl:\n    \"\"\"The Windows 11 common-dialog edit field: SetValue reports success,\n    the value never changes (ledger R27). Falls to real input.\"\"\"\n\n    ControlTypeName = \"EditControl\"\n    Name = \"File name\"\n\n    def __init__(self):\n        self._holder = {\"value\": \"old-name.txt\"}\n\n    def GetValuePattern(self):\n        outer = self\n\n        class VP:\n            @property\n            def Value(self):\n                return outer._holder[\"value\"]\n\n            def SetValue(self, v):\n                outer._holder[\"set_called\"] = True   # ...and does nothing\n        return VP()\n\n\nclass TestSetValueFallback(unittest.TestCase):\n    def _ref(self, control):\n        from autoskill.desktop.refs import RefStore\n        store = RefStore()\n        store.begin_observation()\n        store.add(control, role=\"edit\", name=\"File name\")\n        ref = next(iter(store._map))\n        store.resolve(ref).control = control\n        return store, ref\n\n    def test_lied_set_falls_back_to_real_input(self):\n        from autoskill.desktop import actions\n        ctl = LyingEditControl()\n        store, ref = self._ref(ctl)\n\n        def fake_real(entry, value):\n            ctl._holder[\"value\"] = value        # real input gets through\n            return True\n        orig = actions._real_replace_value\n        actions._real_replace_value = fake_real\n        try:\n            res = actions.set_value(store, ref, \"report.docx\")\n        finally:\n            actions._real_replace_value = orig\n        self.assertEqual(res[\"method\"], \"real_paste\")\n        self.assertEqual(res[\"actual\"], \"report.docx\")\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n\n    def test_reformat_reports_mismatch_without_fallback(self):\n        from autoskill.desktop import actions\n        calls = []\n\n        class Reformats:\n            ControlTypeName = Name = \"Edit\"\n\n            def GetValuePattern(self):\n                outer = self\n\n                class VP:\n                    @property\n                    def Value(self):\n                        return outer._value\n\n                    def SetValue(self, v):\n                        calls.append(v)\n                        outer._value = \"1/2/2026\"   # accepted, reformatted\n                return VP()\n\n            _value = \"old\"\n\n        ctl = Reformats()\n        store, ref = self._ref(ctl)\n        orig = actions._real_replace_value\n        actions._real_replace_value = lambda e, v: calls.append(\"fallback\") or True\n        try:\n            res = actions.set_value(store, ref, \"2026-02-01\")\n        finally:\n            actions._real_replace_value = orig\n        self.assertTrue(res.get(\"mismatch\"))\n        self.assertEqual(calls, [\"2026-02-01\"])   # no fallback fired\n\n    def test_unreadable_value_is_unknown_and_unverified(self):\n        # KT-04 (2026-10-04): a value that cannot be read back is not a\n        # committed effect (it was reported COMMITTED, verified False, before).\n        class Mute:\n            ControlTypeName = Name = \"Edit\"\n\n            def GetValuePattern(self):\n                class VP:\n                    @property\n                    def Value(self):\n                        raise AttributeError(\"unreadable\")\n                    def SetValue(self, v):\n                        pass\n                return VP()\n\n        from autoskill.desktop import actions\n        store, ref = self._ref(Mute())\n        res = actions.set_value(store, ref, \"x\")\n        self.assertFalse(res.get(\"verified\", True))\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n\n    def test_both_paths_ignored_raises_honestly(self):\n        from autoskill.desktop import actions\n        from autoskill.protocol import ProtocolError\n        ctl = LyingEditControl()\n        store, ref = self._ref(ctl)\n        orig = actions._real_replace_value\n        actions._real_replace_value = lambda e, v: False\n        try:\n            with self.assertRaises(ProtocolError) as cm:\n                actions.set_value(store, ref, \"new.txt\")\n        finally:\n            actions._real_replace_value = orig\n        self.assertEqual(cm.exception.error.effect_state.value, \"unknown\")\n\n\nclass TestRealReplaceValue(unittest.TestCase):\n    \"\"\"The real-input path itself, headless: real click, Ctrl+A, paste.\"\"\"\n\n    def test_clicks_selects_all_and_pastes(self):\n        from autoskill.desktop import actions\n\n        sent, pasted, clicked = [], [], []\n\n        class FakeUa:\n            def SendKeys(self, keys, waitTime=0):\n                sent.append(keys)\n\n        class Ctl:\n            ControlTypeName = Name = \"Edit\"\n            def ScrollIntoView(self):\n                pass\n            class _Rect:\n                left, top, right, bottom = 10, 10, 110, 40\n            BoundingRectangle = _Rect()\n            def Click(self, waitTime=0):\n                clicked.append(True)\n\n        from autoskill.desktop.refs import RefStore, ElementRef\n        entry = ElementRef(ref=\"@e1\", control=Ctl(), role=\"edit\", name=\"Edit\",\n                           generation=1)\n\n        orig = (actions._require_uia, actions._require_on_screen, actions._paste)\n        actions._require_uia = lambda: FakeUa()\n        actions._require_on_screen = lambda x, y, e: None\n        actions._paste = lambda ua, text: pasted.append(text) or True\n        try:\n            ok = actions._real_replace_value(entry, \"new name\")\n        finally:\n            actions._require_uia, actions._require_on_screen, actions._paste = orig\n        self.assertTrue(ok)\n        self.assertEqual(clicked, [True])\n        self.assertEqual(sent, [\"{Ctrl}a\"])\n        self.assertEqual(pasted, [\"new name\"])\n\n\nclass TestCloseWindowZombie(unittest.TestCase):\n    \"\"\"R26: a window can ack Close and stay. The result must say so.\"\"\"\n\n    class _WinPat:\n        closed = False\n\n        def Close(self):\n            type(self).closed = True\n            return True\n\n    class Window:\n        Name = \"report.docx - Word\"\n        NativeWindowHandle = 4242\n        ProcessId = None               # _process_name() yields \"\" headlessly\n\n        def GetWindowPattern(self):\n            return TestCloseWindowZombie._WinPat()\n\n    def _run(self, zombie):\n        from autoskill.desktop import actions\n        win = self.Window()\n        state = {\"n\": 0}\n\n        def fake_find(selector):\n            state[\"n\"] += 1\n            if state[\"n\"] == 1:\n                return win                       # the initial lookup\n            return win if zombie else None       # the post-close checks\n\n        orig = actions.find_window\n        actions.find_window = fake_find\n        try:\n            return actions.close_window(\"report.docx\")\n        finally:\n            actions.find_window = orig\n\n    def test_window_actually_closes(self):\n        res = self._run(zombie=False)\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertNotIn(\"zombie\", res)\n\n    def test_zombie_window_is_reported_not_assumed(self):\n        res = self._run(zombie=True)\n        self.assertEqual(res[\"effect_state\"], \"unknown\")\n        self.assertTrue(res.get(\"zombie\"))\n        self.assertIn(\"quit-app\", res.get(\"note\", \"\"))\n\n\nclass TestQuitApp(unittest.TestCase):\n    \"\"\"R29: graceful close first, termination only for what outlives it.\"\"\"\n\n    def test_no_match_is_a_no_op(self):\n        from autoskill.desktop import actions\n        orig = actions._pids_by_name\n        actions._pids_by_name = lambda name: []\n        try:\n            res = actions.quit_app(\"notepad.exe\")\n        finally:\n            actions._pids_by_name = orig\n        self.assertEqual(res[\"effect_state\"], \"none\")\n\n    def test_graceful_exit_closes_windows_without_forcing(self):\n        from autoskill.desktop import actions\n\n        class Win:\n            Name = \"Notes\"\n            ProcessId = 11\n            def GetWindowPattern(self):\n                class WP:\n                    def Close(self):\n                        return True\n                return WP()\n\n        class Root:\n            @staticmethod\n            def GetChildren():\n                return [Win()]\n\n        class Ua:\n            @staticmethod\n            def GetRootControl():\n                return Root()\n\n        orig = (actions._pids_by_name, actions._pid_alive, actions._require_uia)\n        actions._pids_by_name = lambda name: [11]\n        actions._pid_alive = lambda pid: False      # exits on its own\n        actions._require_uia = lambda: Ua()\n        try:\n            res = actions.quit_app(\"notepad.exe\", timeout=1)\n        finally:\n            actions._pids_by_name, actions._pid_alive, actions._require_uia = orig\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n        self.assertEqual(res[\"windows_closed\"], 1)\n        self.assertFalse(res[\"forced\"])\n\n    def test_survivor_is_terminated_and_disclosed(self):\n        import psutil\n        from autoskill.desktop import actions\n        orig = (actions._pids_by_name, actions._pid_alive, actions._require_uia)\n        actions._pids_by_name = lambda name: [9999]\n        actions._pid_alive = lambda pid: True       # never dies gracefully\n        actions._require_uia = lambda: None         # no windows to close\n        real_process = psutil.Process\n        psutil.Process = lambda pid: (_ for _ in ()).throw(\n            psutil.NoSuchProcess(pid))              # pid vanished: done anyway\n        try:\n            res = actions.quit_app(\"winword.exe\", timeout=0.2)\n        finally:\n            psutil.Process = real_process\n            actions._pids_by_name, actions._pid_alive, actions._require_uia = orig\n        self.assertTrue(res[\"forced\"])\n        self.assertEqual(res[\"effect_state\"], \"committed\")\n\n\n@unittest.skipIf(os.name != \"nt\", \"SHFileOperationW is Windows-only\")\nclass TestCopyPaths(unittest.TestCase):\n    \"\"\"R28: one shell call instead of driving Explorer's UI by hand.\"\"\"\n\n    def test_copies_a_file_into_a_folder(self):\n        import tempfile\n        from autoskill.desktop import actions\n        with tempfile.TemporaryDirectory() as td:\n            src = Path(td) / \"a.txt\"\n            src.write_text(\"payload\", encoding=\"utf-8\")\n            dst_dir = Path(td) / \"out\"\n            dst_dir.mkdir()\n            res = actions.copy_paths([str(src)], str(dst_dir))\n            self.assertEqual(res[\"effect_state\"], \"committed\")\n            self.assertEqual((dst_dir / \"a.txt\").read_text(encoding=\"utf-8\"),\n                             \"payload\")\n\n    def test_copies_a_directory_tree(self):\n        import tempfile\n        from autoskill.desktop import actions\n        with tempfile.TemporaryDirectory() as td:\n            folder = Path(td) / \"pack\"\n            (folder / \"sub\").mkdir(parents=True)\n            (folder / \"sub\" / \"b.txt\").write_text(\"inner\", encoding=\"utf-8\")\n            dst = Path(td) / \"out\"\n            dst.mkdir()\n            res = actions.copy_paths([str(folder)], str(dst))\n            self.assertEqual(res[\"effect_state\"], \"committed\")\n            self.assertTrue((dst / \"pack\" / \"sub\" / \"b.txt\").exists())\n\n    def test_missing_source_fails_before_any_copy(self):\n        from autoskill.desktop import actions\n        from autoskill.protocol import ProtocolError\n        with self.assertRaises(ProtocolError):\n            actions.copy_paths([r\"C:\\nowhere\\nope.txt\"], \".\")\n\n    def test_empty_sources_is_a_usage_error(self):\n        from autoskill.desktop import actions\n        from autoskill.protocol import ProtocolError\n        with self.assertRaises(ProtocolError):\n            actions.copy_paths([], r\"C:\\temp\")\n\n\nclass TestNewVerbParsers(unittest.TestCase):\n    def test_quit_app_parses(self):\n        from autoskill.cli import build_parser\n        a = build_parser().parse_args([\"quit-app\", \"WINWORD.EXE\",\n                                       \"--timeout\", \"5\"])\n        self.assertEqual((a.process, a.timeout), (\"WINWORD.EXE\", 5.0))\n\n    def test_copy_takes_sources_then_destination(self):\n        from autoskill.cli import build_parser\n        a = build_parser().parse_args([\"copy\", \"a.txt\", \"b.txt\", \"folder\"])\n        self.assertEqual(a.paths, [\"a.txt\", \"b.txt\", \"folder\"])\n\n\nclass TestBridgeEndpointFallback(unittest.TestCase):\n    \"\"\"A workstation install keeps runtime state in <root>/bridge-home;\n    `rb` must find it without AUTOSKILL_HOME being set. Since KT-01\n    (2026-10-04) an endpoint file counts only when its pid is a live browser\n    of the selected kind, so the browser identity is faked here.\"\"\"\n\n    def test_project_local_bridge_home_is_found(self):\n        import os\n        import tempfile\n        from unittest.mock import patch\n        from autoskill import nmhost\n        with tempfile.TemporaryDirectory() as td:\n            fake_root = Path(td)\n            (fake_root / \"bridge-home\").mkdir()\n            (fake_root / \"bridge-home\" / \"rb-endpoint-chrome-abc.json\").write_text(\n                '{\"port\": 1, \"token\": \"t\", \"pid\": %d, \"instance\": \"abc\"}' % os.getpid(),\n                encoding=\"utf-8\")\n            real_home, real_file = nmhost.home_dir, nmhost.__file__\n            nmhost.home_dir = lambda: fake_root / \"nowhere-default\"\n            nmhost.__file__ = str(fake_root / \"src\" / \"autoskill\" / \"nmhost.py\")\n            try:\n                with patch.object(Path, \"home\", return_value=fake_root / \"user\"), \\\n                        patch.dict(os.environ, {\"AUTOSKILL_BROWSER\": \"chrome\",\n                                                \"AUTOSKILL_BRIDGE_HOME\": \"\",\n                                                \"AUTOSKILL_BRIDGE_INSTANCE\": \"\"}), \\\n                        patch.object(nmhost, \"browser_identity\", return_value=\"chrome\"), \\\n                        patch.object(nmhost, \"is_owner_only\", return_value=True):\n                    got = nmhost._bridge_endpoint_file()\n            finally:\n                nmhost.home_dir = real_home\n                nmhost.__file__ = real_file\n            self.assertEqual(got.parent.name, \"bridge-home\")\n\n    def test_missing_everywhere_raises_the_unavailable_error(self):\n        \"\"\"No endpoint anywhere: the error that `rb._call` maps to\n        DAEMON_UNAVAILABLE (it returned a missing primary path before KT-01).\"\"\"\n        import tempfile\n        from unittest.mock import patch\n        from autoskill import nmhost\n        with tempfile.TemporaryDirectory() as td:\n            fake_root = Path(td)\n            real_home, real_file = nmhost.home_dir, nmhost.__file__\n            nmhost.home_dir = lambda: fake_root / \"default-home\"\n            nmhost.__file__ = str(fake_root / \"src\" / \"autoskill\" / \"nmhost.py\")\n            # The lookup also consults the user's default home, so \"missing\n            # everywhere\" is only true if that is redirected too - otherwise\n            # this machine's real bridge makes the premise false.\n            import pathlib\n            real_user_home = pathlib.Path.home\n            pathlib.Path.home = staticmethod(lambda: fake_root / \"user\")\n            try:\n                with patch.dict(os.environ, {\"AUTOSKILL_BRIDGE_HOME\": \"\",\n                                             \"AUTOSKILL_BRIDGE_INSTANCE\": \"\"}), \\\n                        self.assertRaises(RuntimeError) as ctx:\n                    nmhost._bridge_endpoint_file()\n            finally:\n                nmhost.home_dir = real_home\n                nmhost.__file__ = real_file\n                pathlib.Path.home = real_user_home\n            self.assertIn(\"no autoskill bridge\", str(ctx.exception))\n\n\n\n\nclass TestPostOracleHardening(unittest.TestCase):\n    \"\"\"Fixes from the live Oracle run (S88/Q1-Q6).\"\"\"\n\n    def test_stale_box_model_error_gets_a_hint(self):\n        from autoskill.nmhost import _friendly_rb_error\n        out = _friendly_rb_error('{\"code\":-32000,\"message\":\"Could not compute box model.\"}')\n        self.assertIn(\"stale\", out)\n        self.assertIn(\"rb observe\", out)\n\n    def test_gone_tab_error_gets_a_hint(self):\n        from autoskill.nmhost import _friendly_rb_error\n        out = _friendly_rb_error(\"No tab with given id 42.\")\n        self.assertIn(\"rb tabs\", out)\n\n    def test_unknown_error_passes_through(self):\n        from autoskill.nmhost import _friendly_rb_error\n        self.assertEqual(_friendly_rb_error(\"boom\"), \"boom\")\n\n    def test_rb_wait_parses(self):\n        from autoskill.cli import build_parser\n        a = build_parser().parse_args([\"rb\", \"wait\", \"Approve\",\n                                       \"--role\", \"button\",\n                                       \"--timeout\", \"30\", \"--tab-id\", \"7\"])\n        self.assertEqual((a.name, a.role, a.timeout, a.tab_id),\n                         (\"Approve\", \"button\", 30.0, 7))\n\n    def test_app_path_lookup_rejects_paths_and_unknowns(self):\n        from autoskill.desktop.actions import _app_path_lookup\n        self.assertIsNone(_app_path_lookup(r\"C:\\full\\path\\excel.exe\"))\n        self.assertIsNone(_app_path_lookup(\"definitely-not-real-9x.exe\"))\n\n    def test_confirmation_mirror_file_written_and_cleared(self):\n        import tempfile, threading\n        from autoskill.daemon import ConfirmationBroker\n        with tempfile.TemporaryDirectory() as td:\n            mirror = Path(td) / \"confirmations.json\"\n            b = ConfirmationBroker(mirror)\n            done = threading.Event()\n\n            def asker():\n                b.ask(session=None, method=\"desktop.open_app\",\n                      detail=\"excel.exe\", timeout=5)\n                done.set()\n\n            t = threading.Thread(target=asker)\n            t.start()\n            time.sleep(0.3)                     # ask() is now parked waiting\n            data = json.loads(mirror.read_text(encoding=\"utf-8\"))\n            self.assertEqual(len(data), 1)\n            self.assertEqual(data[0][\"method\"], \"desktop.open_app\")\n            token = data[0][\"token\"]\n            b.answer(token, True)\n            t.join(timeout=5)\n            done.wait(5)\n            data = json.loads(mirror.read_text(encoding=\"utf-8\"))\n            self.assertEqual(data, [])\n\n\n@unittest.skipIf(os.name != \"nt\", \"ledger verbs are exercised on this device\")\nclass TestTableLedger(unittest.TestCase):\n    \"\"\"Recurring-task ledgers: ONE file, appended across sessions.\"\"\"\n\n    def test_ask_mirror_detail_written_live_detail_kept(self):\n        import tempfile, threading\n        from autoskill.daemon import ConfirmationBroker\n        with tempfile.TemporaryDirectory() as td:\n            mirror = Path(td) / \"confirmations.json\"\n            b = ConfirmationBroker(mirror)\n            done = threading.Event()\n\n            def asker():\n                b.ask(session=None, method=\"desktop.batch\",\n                      detail=\"desktop.batch steps: click on @e1 button 'Go' \"\n                             \"(args: count=2, button='right')\",\n                      mirror_detail=\"desktop.batch steps: click on @e1 button 'Go'\",\n                      timeout=5)\n                done.set()\n\n            t = threading.Thread(target=asker)\n            t.start()\n            time.sleep(0.3)                     # ask() is parked waiting\n            data = json.loads(mirror.read_text(encoding=\"utf-8\"))\n            self.assertEqual(len(data), 1)\n            self.assertEqual(data[0][\"detail\"],\n                             \"desktop.batch steps: click on @e1 button 'Go'\")\n            # The LIVE detail (pending()/dashboard/status) keeps the args.\n            self.assertEqual(b.pending()[0][\"detail\"],\n                             \"desktop.batch steps: click on @e1 button 'Go' \"\n                             \"(args: count=2, button='right')\")\n            b.answer(data[0][\"token\"], True)\n            t.join(timeout=5)\n            done.wait(5)\n            self.assertEqual(json.loads(mirror.read_text(encoding=\"utf-8\")), [])\n    def test_ask_one_string_mirrors_detail_verbatim(self):\n        # The NON-batch ask path (one string, no mirror_detail): its mirror\n        # stays byte-identical — pinned with the exact :1572-1593 detail.\n        import tempfile, threading\n        from autoskill.daemon import ConfirmationBroker\n        with tempfile.TemporaryDirectory() as td:\n            mirror = Path(td) / \"confirmations.json\"\n            b = ConfirmationBroker(mirror)\n            done = threading.Event()\n            detail = (\"desktop.click on app.exe / App \\u2014 \"\n                      \"strict mode: every action is confirmed\")\n\n            def asker():\n                b.ask(session=None, method=\"desktop.click\",\n                      detail=detail, timeout=5)\n                done.set()\n\n            t = threading.Thread(target=asker)\n            t.start()\n            time.sleep(0.3)                     # ask() is parked waiting\n            data = json.loads(mirror.read_text(encoding=\"utf-8\"))\n            self.assertEqual(len(data), 1)\n            self.assertEqual(data[0][\"detail\"], detail)  # byte-identical\n            b.answer(data[0][\"token\"], True)\n            t.join(timeout=5)\n            done.wait(5)\n            self.assertEqual(json.loads(mirror.read_text(encoding=\"utf-8\")), [])\n\n    def _tmp(self):\n        import tempfile\n        td = tempfile.TemporaryDirectory()\n        self.addCleanup(td.cleanup)\n        return Path(td.name) / \"ledger.xlsx\"\n\n    def test_create_append_and_read_back(self):\n        from autoskill.desktop.ledger import table_append, table_read\n        f = self._tmp()\n        r = table_append(str(f), [\"S1\\tDriver license\\tSaleh\\tApproved\"],\n                         header=\"Session\\tRequest\\tApplier\\tAction\")\n        self.assertTrue(r[\"created\"])\n        self.assertEqual(r[\"rows_added\"], 1)\n        r2 = table_append(str(f), [\"S2\\tEmail change\\tAlia\\tApproved\"])\n        self.assertFalse(r2[\"created\"])\n        self.assertEqual(r2[\"rows_added\"], 1)\n        out = table_read(str(f))\n        self.assertEqual(out[\"total_rows\"], 3)      # header + 2\n        self.assertEqual(out[\"rows\"][1][0], \"S1\")\n        self.assertEqual(out[\"rows\"][2][3], \"Approved\")\n\n    def test_header_mismatch_is_refused(self):\n        from autoskill.desktop.ledger import table_append\n        from autoskill.protocol import ProtocolError\n        f = self._tmp()\n        table_append(str(f), [\"a\\tb\"], header=\"A\\tB\")\n        with self.assertRaises(ProtocolError):\n            table_append(str(f), [\"c\\td\"], header=\"X\\tY\")\n\n    def test_dedup_skips_replayed_rows(self):\n        from autoskill.desktop.ledger import table_append\n        f = self._tmp()\n        table_append(str(f), [\"DL-1\\tApproved\"], header=\"Task\\tAction\")\n        r = table_append(str(f), [\"DL-1\\tApproved\", \"DL-2\\tSkipped\"],\n                         dedup_cols=\"1\")\n        self.assertEqual(r[\"rows_added\"], 1)\n        self.assertEqual(r[\"rows_skipped_duplicate\"], 1)\n\n    def test_create_without_header_is_a_usage_error(self):\n        from autoskill.desktop.ledger import table_append\n        from autoskill.protocol import ProtocolError\n        with self.assertRaises(ProtocolError):\n            table_append(str(self._tmp()), [\"a\\tb\"])\n\n    def test_parser(self):\n        from autoskill.cli import build_parser\n        a = build_parser().parse_args(\n            [\"table\", \"l.xlsx\", \"--header\", \"A\\tB\", \"--row\", \"1\\t2\",\n             \"--dedup\", \"1\"])\n        self.assertEqual(a.header, \"A\\tB\")\n        self.assertEqual(a.row, [\"1\\t2\"])\n        self.assertEqual(a.dedup, \"1\")\n\n\nclass TestStartAppLookup(unittest.TestCase):\n    \"\"\"Store apps (Power BI, Power Automate) launch via their AppID.\"\"\"\n\n    def test_appid_passthrough(self):\n        from autoskill.desktop.actions import _start_app_lookup\n        self.assertEqual(\n            _start_app_lookup(r\"Microsoft.PowerAutomateDesktop_8wekyb3d8bbwe!PAD.Console\"),\n            r\"Microsoft.PowerAutomateDesktop_8wekyb3d8bbwe!PAD.Console\")\n\n    def test_lookup_finds_installed_store_apps(self):\n        from autoskill.desktop.actions import _start_app_lookup\n        # This machine has Power BI Desktop and Power Automate (S95 inventory)\n        appid = _start_app_lookup(\"Power BI Desktop\")\n        self.assertTrue(appid and \"!\" in appid)\n        pad = _start_app_lookup(\"Power Automate\")\n        self.assertTrue(pad and \"!\" in pad)\n\n    def test_nonsense_name_returns_none(self):\n        from autoskill.desktop.actions import _start_app_lookup\n        self.assertIsNone(_start_app_lookup(\"definitely-not-an-app-9x\"))\n\n\nclass TestAppsInventory(unittest.TestCase):\n    \"\"\"S96: the device's own registries tell us what is installed.\"\"\"\n\n    def test_inventory_counts_and_finds_office(self):\n        from autoskill.desktop.actions import installed_apps\n        out = installed_apps()\n        self.assertGreater(out[\"total\"], 50)      # a real device has many\n        hit = installed_apps(find=\"Excel\")\n        self.assertTrue(any(\"Excel\" in a[\"name\"] for a in hit[\"apps\"]))\n\n    def test_inventory_finds_store_apps(self):\n        from autoskill.desktop.actions import installed_apps\n        hit = installed_apps(find=\"Power BI\")\n        self.assertTrue(any(a[\"kind\"] == \"start\" for a in hit[\"apps\"]))\n\n    def test_apps_parser(self):\n        from autoskill.cli import build_parser\n        a = build_parser().parse_args([\"apps\", \"--find\", \"paint\"])\n        self.assertEqual(a.find, \"paint\")\n\n\nclass TestAppClassification(unittest.TestCase):\n    \"\"\"S97: apps are tagged with how they want to be driven.\"\"\"\n\n    def test_uwp_filter_and_strategies(self):\n        from autoskill.desktop.actions import installed_apps\n        out = installed_apps(find=\"Power BI\")\n        self.assertTrue(all(a[\"cls\"] == \"uwp\" for a in out[\"apps\"]))\n        self.assertIn(\"win32\", out[\"strategies\"])\n        self.assertIn(\"uwp\", out[\"strategies\"])\n        only = installed_apps(cls=\"uwp\")\n        self.assertTrue(only[\"apps\"])\n        self.assertTrue(all(a[\"cls\"] == \"uwp\" for a in only[\"apps\"]))\n\n\n# Kept last on purpose: unittest.main() runs at import time, so any\n# class defined after it is silently never collected. Four classes\n# (12 tests) sat below this line and never ran under the documented\n# command, which is why the ledger's count read higher than reality.\nif __name__ == \"__main__\":\n    unittest.main(verbosity=2)\n");
